WITH matched AS (SELECT a.*, sub.id AS subscription_id, sub.plan, sub.monthly_fee FROM accounts a LEFT JOIN subscriptions sub ON a.customer_id = sub.customer_id AND a.opened_date >= sub.start_date AND a.opened_date <= DATE_ADD(sub.end_date, 7)) SELECT CASE WHEN subscription_id >= 10 THEN 'PREMIUM' ELSE 'STANDARD' END AS subscription_id_tier, DATE_TRUNC('WEEK', opened_date) AS week_start, DATE_TRUNC('YEAR', opened_date) AS year_start, COUNT(*) FILTER (WHERE account_type = 'CREDIT') AS credit_rows, COUNT(*) AS num_rows FROM matched GROUP BY CASE WHEN subscription_id >= 10 THEN 'PREMIUM' ELSE 'STANDARD' END, DATE_TRUNC('WEEK', opened_date), DATE_TRUNC('YEAR', opened_date) ORDER BY num_rows DESC;
